<?php
/** TEMP PS S1688 mo — v0.8 (4 versijos): f=produktas — terra laukai = REALI product segmento prekė (ANTR pagal jautrumo taisyklę) + PRODUCT kampanija; f=likusieji — terra laukai atgal į calc + CALC, GENERIC, GENERIC-B kampanijos; f=html_<v> — užpildytas HTML naršyklės peržiūrai; f=nars — 4 ekrano nuotraukos 390 px. __ADR__/__PRIV__ pakeičiami WC adresu / privatumo puslapiu. */
add_action('init', function(){
  if (!isset($_GET['ps_s1688mo'])) return; global $wpdb; $o=array('v'=>'S1688 mo'); $f=$_GET['ps_s1688mo']; $t=Petshop_Relaunch::t(); $up=wp_upload_dir();
  $tok=Petshop_Sender_Adapter::get_stored_token('marketing');
  $api=function($m,$p,$b=null) use($tok){ $a=array('method'=>$m,'timeout'=>25,'headers'=>array('Authorization'=>'Bearer '.$tok,'Accept'=>'application/json','Content-Type'=>'application/json')); if($b!==null) $a['body']=wp_json_encode($b);
    $r=wp_remote_request('https://api.sender.net/v2'.$p,$a); if(is_wp_error($r)) return array('code'=>0,'err'=>$r->get_error_message()); return array('code'=>wp_remote_retrieve_response_code($r),'body'=>json_decode(wp_remote_retrieve_body($r),true)); };
  $adr=trim(get_option('woocommerce_store_address').' '.get_option('woocommerce_store_address_2')).', '.get_option('woocommerce_store_postcode').' '.get_option('woocommerce_store_city'); $priv=get_privacy_policy_url()?:home_url('/privatumo-politika/');
  $HTML=array('calc'=>'','product'=>'','generic'=>'','genericb'=>'');
  $html=function($k) use($HTML,$adr,$priv){ return str_replace(array('__ADR__','__PRIV__'),array($adr,$priv),base64_decode($HTML[$k])); };
  $jautri=function($pav){ return (bool)preg_match('/veterinar|diet|hypoaller|hipoalerg|sensitiv|renal|urinary|gastro|hepatic|obesity|diabet|dermat|convalesc|recovery|mobility|cardiac|jautr|inkst|šlapim|virškin|alerg/iu',$pav); };
  $trumpai=function($pav){ $s=preg_replace('/\s*[,(]?\s*\d+(?:[,.]\d+)?\s?(kg|g|ml|l|vnt|x)\b.*$/iu','',$pav); $s=trim($s," \t-–,:;"); if($s===mb_strtoupper($s)) $s=mb_convert_case(mb_strtolower($s),MB_CASE_TITLE,'UTF-8'); if(mb_strlen($s)>34){ $w=explode(' ',$s); $s=''; foreach($w as $x){ if(mb_strlen($s.' '.$x)>34) break; $s=trim($s.' '.$x); } } return trim($s," -–,:;")?:$pav; };
  $jpg=function($pid){ global $wpdb; $up=wp_upload_dir(); $f=$up['basedir'].'/ps-relaunch/'.$pid.'.jpg'; if(!file_exists($f)){ $pr=wc_get_product($pid); $iid=$pr?$pr->get_image_id():0; $src=$iid?get_attached_file($iid):''; if($src){ wp_mkdir_p(dirname($f)); $ed=wp_get_image_editor($src); if(!is_wp_error($ed)){ $ed->resize(400,400,false); $ed->save($f,'image/jpeg'); } } } return file_exists($f)?$up['baseurl'].'/ps-relaunch/'.$pid.'.jpg':''; };
  $calc_laukai=function() use($wpdb,$t,$jpg){ $row=$wpdb->get_row("SELECT * FROM $t WHERE email='terra@gyvunai.lt'",ARRAY_A); $d=json_decode($row['duomenys'],true); $pr=wc_get_product(12466); $pak='Pakuotės'; if(preg_match('/(\d+(?:[,.]\d+)?)\s?kg/iu',$pr->get_name(),$m)) $pak=str_replace('.',',',$m[1]).' kg maišo';
    $fl=array('PS_HERO_SEG'=>'calc','PS_HERO_PAV'=>$d['pav'],'PS_HERO_KAINA'=>number_format((float)$d['kaina'],2,',','').' €','PS_HERO_IMG'=>$jpg(12466),'PS_HERO_URL'=>$d['url'],'PS_HERO_GYV'=>'šuniui','PS_HERO_ANTR'=>'','PS_HERO_KODEL'=>'nes esate pirkę petshop.lt','PS_HERO_PAK'=>$pak);
    foreach($d['eilutes'] as $i=>$e){ $n=$i+1; $fl["PS_HERO_KG$n"]=$e['kg'].' kg'; $fl["PS_HERO_EUR$n"]='nuo '.$e['eur_nuo'].' €'; $fl["PS_HERO_INFO$n"]=$e['g'].' g/d · maišo užtenka '.$e['d'].' d.'; $fl["PS_HERO_U$n"]=$e['url']; $fl["PS_HERO_D$n"]=$e['d']; if($n===2){ $fl['PS_HERO_G2']=$e['g'].' g'; } } return $fl; };
  $prod_laukai=function() use($wpdb,$t,$jpg,$jautri,$trumpai){ $pid=(int)$wpdb->get_var("SELECT product_id FROM $t WHERE consent=1 AND segmentas='product' AND product_id IS NOT NULL GROUP BY product_id ORDER BY COUNT(*) DESC, product_id LIMIT 1"); $pr=wc_get_product($pid); $cid=$wpdb->get_var("SELECT cid FROM $t WHERE email='terra@gyvunai.lt'");
    $url=add_query_arg(array('utm_source'=>'sender','utm_medium'=>'email','utm_campaign'=>'relaunch','utm_content'=>'product','cid'=>$cid),$pr->get_permalink()); $pav=$pr->get_name();
    $fl=array('PS_HERO_SEG'=>'product','PS_HERO_PAV'=>$pav,'PS_HERO_KAINA'=>number_format((float)wc_get_price_to_display($pr),2,',','').' €','PS_HERO_IMG'=>$jpg($pid),'PS_HERO_URL'=>$url,'PS_HERO_GYV'=>'','PS_HERO_ANTR'=>$jautri($pav)?'Pažįstamos prekės':$trumpai($pav),'PS_HERO_KODEL'=>'nes esate pirkę petshop.lt','PS_HERO_PAK'=>'');
    foreach(array(1,2,3) as $n){ $fl["PS_HERO_KG$n"]=''; $fl["PS_HERO_EUR$n"]=''; $fl["PS_HERO_INFO$n"]=''; $fl["PS_HERO_U$n"]=''; } $fl['PS_HERO_G2']=''; foreach(array(1,2,3) as $n) $fl["PS_HERO_D$n"]=''; return array($fl,$pid,$pav,$jautri($pav)); };
  $kamp=function($k,$title,$subject,$pre,$c) use($api,$html){ $b=array('title'=>$title.' '.date('H:i'),'subject'=>$subject,'from'=>'Petshop.lt','reply_to'=>'terra@petshop.lt','content_type'=>'html','content'=>$html($k),'groups'=>array('bDxp2q'),'preheader'=>$pre);
    $r=$api('POST','/campaigns',$b); $id=$r['body']['data']['id']??''; $out=array('kurti'=>$r['code'],'id'=>$id,'err'=>$r['body']['errors']??null); if($id){ $s=$api('POST','/campaigns/'.$id.'/send'); $out['send']=$s['code']; } return $out; };
  $fill=function($k,$fl) use($html){ $s=$html($k); foreach($fl as $key=>$v){ $s=str_replace('{{'.strtolower($key).'}}',$v,$s); } $s=preg_replace_callback('/\{\{\s*(ps_hero_\w+)\s*\|\s*default:\s*"([^"]*)"\s*\}\}/',function($m) use($fl){ $v=$fl[strtoupper($m[1])]??''; return $v!==''?$v:$m[2]; },$s); return str_replace(array('{{unsubscribe_link}}','{{unsubscribe_text}}'),array('#','Atsisakyti laiškų'),$s); };
  $o['adr']=$adr; $o['priv']=$priv;
  if($f==='produktas'){ $r=$api('GET','/fields?limit=100'); $yra=array(); foreach((array)($r['body']['data']??array()) as $x) $yra[$x['title']]=1; foreach(array('PS_HERO_D1','PS_HERO_D3') as $l){ $o[$l]=isset($yra[$l])?'buvo':$api('POST','/fields',array('title'=>$l,'type'=>'text'))['code']; } list($fl,$pid,$pav,$j)=$prod_laukai(); $o['preke']=array('pid'=>$pid,'pav'=>$pav,'jautri'=>$j,'antr'=>$fl['PS_HERO_ANTR'],'img'=>$fl['PS_HERO_IMG']); $p=$api('PATCH','/subscribers/terra%40gyvunai.lt',array('fields'=>$fl)); $o['patch']=$p['code'];
    $o['product']=$kamp('product','TEST relaunch PRODUCT v0.8','{{ps_hero_antr}} – {{ps_hero_kaina}}','Anksčiau rinkotės šią prekę pas mus. Štai kur ją rasite atnaujintame Petshop.lt.',null); }
  elseif($f==='likusieji'){ $fl=$calc_laukai(); $p=$api('PATCH','/subscribers/terra%40gyvunai.lt',array('fields'=>$fl)); $o['patch']=$p['code'];
    $o['calc']=$kamp('calc','TEST relaunch CALC v0.8','{{ps_hero_kg2}} {{ps_hero_gyv}} – {{ps_hero_d2}} dienų iš vieno maišo?','{{ps_hero_eur2}} per dieną. Skaičiavome pagal maistą, kurį anksčiau pirkote pas mus.',null);
    $o['generic']=$kamp('generic','TEST relaunch GENERIC v0.8','Jūsų ankstesni Petshop pirkiniai niekur nedingo','Svetainė nauja. Užsakymų istorija išsaugota – prireikus galėsite ją vėl peržiūrėti.',null);
    $o['genericb']=$kamp('genericb','TEST relaunch GENERIC-B v0.8','Petshop.lt persikėlė į naują svetainę','Prenumeruojate mūsų naujienas. Nieko daryti nereikia.',null); }
  elseif(strpos($f,'html_')===0){ $k=substr($f,5); if($k==='product'){ list($fl)=$prod_laukai(); } else { $fl=$calc_laukai(); if($k==='genericb') $fl['PS_HERO_KODEL']='nes užsiprenumeravote petshop.lt naujienas'; } header('Content-Type: text/html; charset=utf-8'); echo $fill($k,$fl); exit; }
  elseif($f==='nars'){ foreach(array('calc','product','generic','genericb') as $k) $o['shots'][]=array('n'=>'s1688_v07_'.$k,'u'=>home_url('/?ps_s1688mo=html_'.$k),'w'=>390,'h'=>844,'full'=>1); }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT); exit;
});
